-- 203: Original BrillaPrep WASSCE BrillaPrep transitional Leatherwork beta content blueprint questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_203_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_203_guard;
INSERT INTO _migration_203_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_001' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_1' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which description best identifies kip in leather classification?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A goat skin selected mainly for its tight grain and small area","B. The lower flesh split removed from any heavy hide during splitting","C. A bovine hide from an animal older than a calf but lighter than a mature cow hide","D. A mature cow hide classified by its finished colour rather than age and weight"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Kip occupies an intermediate bovine class between calfskin and mature cow hide, so its area, thickness and fibre character differ from both lighter calfskin and heavier cow hide. Therefore the correct answer is C: A bovine hide from an animal older than a calf but lighter than a mature cow hide.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_001' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_203_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_002' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_1' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How does split leather differ from grained leather made from the same hide?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Grained leather is commonly the flesh split after a surface pattern has been printed on it","B. Split leather retains much of the natural grain but is cut into smaller panels","C. Split and grained leather describe identical layers but different dye colours","D. Split leather comes from a lower layer and lacks the original natural grain surface"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Mechanical splitting separates hide layers: the grain layer retains the natural outer surface, while a lower split can be finished or embossed but does not possess that original grain. Therefore the correct answer is D: Split leather comes from a lower layer and lacks the original natural grain surface.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_002' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_203_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_003' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_1' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of buffing leather during surface preparation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Apply pigment mechanically while leaving the surface texture unchanged","B. Remove thickness evenly through the whole hide in the same way as splitting","C. Compress the grain with a glazing tool until it becomes a firm polished surface","D. Use controlled abrasion to level defects or raise a uniform nap for the intended finish"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Buffing uses an abrasive action on the grain or flesh side to reduce surface irregularities or develop a controlled nap, depending on whether corrected grain, nubuck or suede is required. Therefore the correct answer is D: Use controlled abrasion to level defects or raise a uniform nap for the intended finish.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_003' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_203_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_004' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_1' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What fundamental change does tanning produce in a prepared pelt?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It removes hair by alkaline swelling without stabilising the collagen","B. It stabilises collagen against putrefaction and excessive water sensitivity","C. It preserves the raw pelt temporarily by drawing out moisture with salt","D. It lubricates already tanned fibres so the dried leather remains flexible"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Tanning agents create stabilising interactions in the collagen structure, converting a perishable pelt into leather with improved biological, wet and thermal stability. Therefore the correct answer is B: It stabilises collagen against putrefaction and excessive water sensitivity.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_004' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_001', 'topic_was_leatherwork_b004_1', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Which description best identifies kip in leather classification?', 'multiple_choice', NULL, '["A. A goat skin selected mainly for its tight grain and small area","B. The lower flesh split removed from any heavy hide during splitting","C. A bovine hide from an animal older than a calf but lighter than a mature cow hide","D. A mature cow hide classified by its finished colour rather than age and weight"]', 'C', 'Kip occupies an intermediate bovine class between calfskin and mature cow hide, so its area, thickness and fibre character differ from both lighter calfskin and heavier cow hide. Therefore the correct answer is C: A bovine hide from an animal older than a calf but lighter than a mature cow hide.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_1', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_002', 'topic_was_leatherwork_b004_1', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'How does split leather differ from grained leather made from the same hide?', 'multiple_choice', NULL, '["A. Grained leather is commonly the flesh split after a surface pattern has been printed on it","B. Split leather retains much of the natural grain but is cut into smaller panels","C. Split and grained leather describe identical layers but different dye colours","D. Split leather comes from a lower layer and lacks the original natural grain surface"]', 'D', 'Mechanical splitting separates hide layers: the grain layer retains the natural outer surface, while a lower split can be finished or embossed but does not possess that original grain. Therefore the correct answer is D: Split leather comes from a lower layer and lacks the original natural grain surface.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_1', 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_003', 'topic_was_leatherwork_b004_1', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What is the purpose of buffing leather during surface preparation?', 'multiple_choice', NULL, '["A. Apply pigment mechanically while leaving the surface texture unchanged","B. Remove thickness evenly through the whole hide in the same way as splitting","C. Compress the grain with a glazing tool until it becomes a firm polished surface","D. Use controlled abrasion to level defects or raise a uniform nap for the intended finish"]', 'D', 'Buffing uses an abrasive action on the grain or flesh side to reduce surface irregularities or develop a controlled nap, depending on whether corrected grain, nubuck or suede is required. Therefore the correct answer is D: Use controlled abrasion to level defects or raise a uniform nap for the intended finish.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_1', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_004', 'topic_was_leatherwork_b004_1', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What fundamental change does tanning produce in a prepared pelt?', 'multiple_choice', NULL, '["A. It removes hair by alkaline swelling without stabilising the collagen","B. It stabilises collagen against putrefaction and excessive water sensitivity","C. It preserves the raw pelt temporarily by drawing out moisture with salt","D. It lubricates already tanned fibres so the dried leather remains flexible"]', 'B', 'Tanning agents create stabilising interactions in the collagen structure, converting a perishable pelt into leather with improved biological, wet and thermal stability. Therefore the correct answer is B: It stabilises collagen against putrefaction and excessive water sensitivity.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_1', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_leatherwork_b004_001', 'q_was_leatherwork_b004_002', 'q_was_leatherwork_b004_003', 'q_was_leatherwork_b004_004');
